import pytest
from calculator import divide

def test_divide_exact():
    assert divide(7, 2) == 3.5

def test_divide_negative():
    assert divide(-7, 2) == -3.5

def test_divide_zero_denominator():
    with pytest.raises(ValueError):
        divide(1, 0)

